describe('Snackbar Message on Clipboard Copy', () => {
  beforeEach(() => {
    cy.visit('/text-editor');
  });

  it('should display success snackbar message after copying text to clipboard', () => {
    // Intercept the clipboard API
    cy.intercept('POST', '/api/clipboard/copy').as('copyClipboard');

    // Get the text to copy
    cy.get('[data-testid="text-to-copy"]').should('be.visible');
    cy.get('[data-testid="text-to-copy"]').should('contain', 'Hello, World!');

    // Copy the text
    cy.get('[data-testid="copy-button"]').click();

    // Wait for the clipboard API call
    cy.wait('@copyClipboard');

    // Verify snackbar is visible
    cy.get('[data-testid="snackbar"]').should('be.visible');
    cy.get('[data-testid="snackbar-message"]').should('contain', 'Text copied to clipboard');

    // Verify snackbar has a success class
    cy.get('[data-testid="snackbar-message"]').should('have.class', 'success');

    // Verify snackbar has a close button
    cy.get('[data-testid="snackbar-close-btn"]').should('be.visible');

    // Verify snackbar is removed after clicking close
    cy.get('[data-testid="snackbar-close-btn"]').click();
    cy.get('[data-testid="snackbar"]').should('not.exist');
  });

  it('should not display snackbar when clipboard API fails', () => {
    // Intercept the clipboard API with a failure
    cy.intercept('POST', '/api/clipboard/copy', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('copyClipboardFail');

    // Get the text to copy
    cy.get('[data-testid="text-to-copy"]').should('be.visible');
    cy.get('[data-testid="text-to-copy"]').should('contain', 'Hello, World!');

    // Attempt to copy the text
    cy.get('[data-testid="copy-button"]').click();

    // Wait for the failed clipboard API call
    cy.wait('@copyClipboardFail');

    // Verify snackbar is not displayed
    cy.get('[data-testid="snackbar"]').should('not.exist');

    // Verify error message is displayed instead
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to copy text');

    // Verify error message has a failure class
    cy.get('[data-testid="error-message"]').should('have.class', 'error');
  });
});
